import pytest

from bedrock_protocol import v1001, v2168, v2225

nbt = v2225.nbt

# generated by gophertunnel b8bd735:
# packet.BlockActorData{Position: protocol.BlockPos{-1, 320, 3}, NBTData: map[string]any{"id": "Chest"}}
CHEST = bytes.fromhex("018005060a000802696405436865737400")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{Position: protocol.BlockPos{1, 2, 3}}
EMPTY_TAG = bytes.fromhex("0204060a0000")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{Position: protocol.BlockPos{-1, -1, -1}}
NEGATIVE_POSITION = bytes.fromhex("0101010a0000")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{NBTData: map[string]any{"a": []map[string]any{}}}
EMPTY_COMPOUND_LIST = bytes.fromhex("0000000a000901610a0000")

# generated by gophertunnel b8bd735:
# packet.BlockActorData{NBTData: map[string]any{"o": []any{[]string{}, []int64{}}}}
NESTED_EMPTY_LISTS = bytes.fromhex("0000000a0009016f09040800040000")

GOLDENS = [
    pytest.param(
        v2225.BlockActorDataPacket(
            pos=v2225.BlockPos(x=-1, y=320, z=3),
            data=nbt.CompoundTag({"id": nbt.StringTag("Chest")}),
        ),
        CHEST,
        id="chest",
    ),
    pytest.param(v2225.BlockActorDataPacket(pos=v2225.BlockPos(x=1, y=2, z=3)), EMPTY_TAG, id="empty-tag"),
    pytest.param(
        v2225.BlockActorDataPacket(pos=v2225.BlockPos(x=-1, y=-1, z=-1)),
        NEGATIVE_POSITION,
        id="negative-position",
    ),
    pytest.param(
        v2225.BlockActorDataPacket(data=nbt.CompoundTag({"a": nbt.ListTag(type=10)})),
        EMPTY_COMPOUND_LIST,
        id="empty-list-keeps-its-element-type",
    ),
    pytest.param(
        v2225.BlockActorDataPacket(
            data=nbt.CompoundTag({"o": nbt.ListTag([nbt.ListTag(type=8), nbt.ListTag(type=4)])}),
        ),
        NESTED_EMPTY_LISTS,
        id="nested-empty-lists-keep-their-element-types",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_block_actor_data_is_packet_56(version):
    assert version.PACKETS[56] is version.BlockActorDataPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_actor_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_block_actor_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.xfail(strict=True, reason="binding gap: ListTag has no clear()")
def test_clearing_a_list_resets_its_type():
    tags = nbt.ListTag([nbt.IntTag(1)])
    tags.clear()
    assert tags.type == 0


def test_a_list_built_in_code_takes_its_type_from_the_first_element():
    tags = nbt.ListTag()
    assert tags.type == 0
    tags.append(nbt.IntTag(1))
    assert tags.type == 3


def test_a_list_rejects_an_element_of_another_type():
    tags = nbt.ListTag([nbt.IntTag(1)])
    with pytest.raises(ValueError, match="share one type"):
        tags.append(nbt.StringTag("x"))


def test_a_typed_empty_list_rejects_an_element_of_another_type():
    with pytest.raises(ValueError, match="share one type"):
        nbt.ListTag(type=10).append(nbt.IntTag(1))


def test_a_typed_empty_list_differs_from_an_untyped_one():
    assert nbt.ListTag(type=10) != nbt.ListTag()


def test_a_list_rejects_a_type_that_is_not_a_tag_type():
    with pytest.raises(ValueError, match="not a tag type"):
        nbt.ListTag(type=12)
